import { execFileSync } from "node:child_process";
import { appendFileSync, existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { PROJECT_JSON } from "./constants.js";
import { isInsideGitWorkTree } from "./file-helpers.js";

/** The first line of the block `flisk up` writes. A .gitignore that has it is never touched again, so a team can edit it. */
export const GENERATED_ROOT_BLOCK_START =
  "# >>> Flisk generated files in the repository root (#3030)";
const BLOCK_END = "# <<< Flisk generated files";
const GENERATED_HEADER = "SYSTEM-GENERATED BY Flisk CLI";
const LOCKFILES = ["bun.lock", "bun.lockb", "package-lock.json", "pnpm-lock.yaml", "yarn.lock"];

/** True when git tracks the path or anything under it. Unknown (git failed) counts as tracked: nothing is hidden by mistake. */
function isTracked(projectRoot: string, relativePath: string): boolean {
  try {
    const out = execFileSync("git", ["ls-files", "--", relativePath], {
      cwd: projectRoot,
      encoding: "utf-8",
      timeout: 5000,
      stdio: ["ignore", "pipe", "ignore"],
    });
    return out.trim() !== "";
  } catch {
    return true;
  }
}

function isIgnored(projectRoot: string, relativePath: string): boolean {
  try {
    execFileSync("git", ["check-ignore", "-q", "--", relativePath], {
      cwd: projectRoot,
      timeout: 5000,
      stdio: "ignore",
    });
    return true;
  } catch {
    return false;
  }
}

function discoveryPathsOf(projectRoot: string): string[] | null {
  try {
    const config = JSON.parse(readFileSync(resolve(projectRoot, ".flisk", PROJECT_JSON), "utf-8"));
    const paths = config?.discovery?.paths;
    return Array.isArray(paths) ? paths : null;
  } catch {
    return null;
  }
}

/** The root package.json Flisk generates (`ensureRootWorkspaceManifest`): exactly its keys, workspaces = discovery paths. */
function isGeneratedWorkspaceManifest(projectRoot: string): boolean {
  const file = resolve(projectRoot, "package.json");
  if (!existsSync(file)) return false;
  try {
    const manifest = JSON.parse(readFileSync(file, "utf-8"));
    const keys = Object.keys(manifest).sort().join(",");
    const paths = discoveryPathsOf(projectRoot);
    return (
      keys === "name,private,type,version,workspaces" &&
      manifest.private === true &&
      manifest.type === "module" &&
      paths !== null &&
      JSON.stringify(manifest.workspaces) === JSON.stringify(paths)
    );
  } catch {
    return false;
  }
}

function fileHasGeneratedHeader(file: string): boolean {
  try {
    return readFileSync(file, "utf-8").includes(GENERATED_HEADER);
  } catch {
    return false;
  }
}

/**
 * Adds the files Flisk generates in the repository root to the project's .gitignore, in one marked block, once (#3030):
 * the workspace `package.json` and the lockfiles beside it, `.tiltignore`, `shared-platform-engineering/` and the generated
 * `services/platform/database-management/docker-compose.yml`. Only inside a git work tree, and never for a path git already
 * tracks (a team's own `package.json` or `.tiltignore` stays as it is). An existing block is left alone, so deleting a
 * line is how a team keeps committing that file. Returns the entries it wrote.
 */
export function ensureGeneratedRootIgnored(projectRoot: string): string[] {
  if (!isInsideGitWorkTree(projectRoot)) return [];
  const gitignorePath = resolve(projectRoot, ".gitignore");
  const existing = existsSync(gitignorePath) ? readFileSync(gitignorePath, "utf-8") : "";
  if (existing.includes(GENERATED_ROOT_BLOCK_START)) return [];

  const candidates: string[] = [];
  if (isGeneratedWorkspaceManifest(projectRoot)) {
    candidates.push("package.json", ...LOCKFILES);
  }
  if (fileHasGeneratedHeader(resolve(projectRoot, ".tiltignore"))) candidates.push(".tiltignore");
  if (existsSync(resolve(projectRoot, "shared-platform-engineering"))) {
    candidates.push("shared-platform-engineering/");
  }
  const databaseCompose = "services/platform/database-management/docker-compose.yml";
  if (fileHasGeneratedHeader(resolve(projectRoot, databaseCompose))) {
    candidates.push(databaseCompose);
  }

  const entries = candidates
    .filter((path) => !isTracked(projectRoot, path.replace(/\/$/, "")))
    .filter((path) => !isIgnored(projectRoot, path.replace(/\/$/, "")))
    .map((path) => `/${path}`);
  if (entries.length === 0) return [];

  const prefix = existing === "" ? "" : existing.endsWith("\n") ? "\n" : "\n\n";
  const lines = [
    GENERATED_ROOT_BLOCK_START,
    "# Written by flisk once. Delete a line to commit that file; flisk will not add it again.",
    ...entries,
    BLOCK_END,
  ];
  appendFileSync(gitignorePath, `${prefix}${lines.join("\n")}\n`);
  return entries.map((entry) => entry.slice(1));
}
